//! Typed identifiers. Every primary key is a UUIDv7 generated by the application (PLAN §8),
//! wrapped in its own type so a `SiteId` can never be passed where a `TenantId` belongs.

use std::fmt;
use std::str::FromStr;

use uuid::Uuid;

macro_rules! id_type {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        pub struct $name(Uuid);

        impl $name {
            /// A new, time-ordered UUIDv7 identifier.
            #[must_use]
            pub fn new() -> Self {
                Self(Uuid::now_v7())
            }

            /// Wraps an identifier read from storage.
            #[must_use]
            pub const fn from_uuid(uuid: Uuid) -> Self {
                Self(uuid)
            }

            /// The underlying UUID, for binding to queries.
            #[must_use]
            pub const fn as_uuid(self) -> Uuid {
                self.0
            }
        }

        impl Default for $name {
            fn default() -> Self {
                Self::new()
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                fmt::Display::fmt(&self.0, f)
            }
        }

        impl FromStr for $name {
            type Err = uuid::Error;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Uuid::parse_str(s).map(Self)
            }
        }
    };
}

id_type!(
    /// A tenant: one Shopify store or one organization. Every tenant-owned row carries it.
    TenantId
);
id_type!(
    /// A site whose pages are scanned.
    SiteId
);
id_type!(
    /// An installed Shopify shop.
    ShopId
);
id_type!(
    /// One scan of a site.
    ScanId
);
id_type!(
    /// A deduplicated finding: one rule failing at one template location.
    FindingId
);
id_type!(
    /// A proposed or applied fix.
    FixId
);
id_type!(
    /// A person who signs in to the standalone dashboard or approves a fix.
    UserId
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_ids_are_version_7() {
        assert_eq!(TenantId::new().as_uuid().get_version_num(), 7);
        assert_eq!(FindingId::new().as_uuid().get_version_num(), 7);
    }

    #[test]
    fn ids_created_later_sort_later() {
        let first = ScanId::new();
        let second = ScanId::new();
        assert!(first < second);
    }

    #[test]
    fn round_trips_through_its_string_form() {
        let id = SiteId::new();
        let parsed: SiteId = id.to_string().parse().unwrap();
        assert_eq!(parsed, id);
    }

    #[test]
    fn rejects_malformed_strings() {
        assert!("not-a-uuid".parse::<FixId>().is_err());
    }

    #[test]
    fn wraps_and_unwraps_an_existing_uuid() {
        let raw = Uuid::now_v7();
        assert_eq!(ShopId::from_uuid(raw).as_uuid(), raw);
    }
}
